SELECT 
FROM ss_sandbox_resize_record
WHERE sandbox_record_id = #{sandboxRecordId,jdbcType=BIGINT}
ORDER BY started_at DESC, id DESC
LIMIT #{limit}

SELECT 
FROM ss_sandbox_resize_record
WHERE 1 = 1

    AND sandbox_record_id = #{sandboxRecordId,jdbcType=BIGINT}


    AND user_code = #{userCode,jdbcType=VARCHAR}


    AND sandbox_id = #{sandboxId,jdbcType=VARCHAR}

ORDER BY started_at DESC, id DESC
LIMIT #{limit}
